plural <- function(n) {
  mod10 <- n %% 10
  mod100 <- n %% 100
  if (mod10 == 1 && mod100 != 11) return("one")
  if (mod10 >= 2 && mod10 <= 9 && (mod100 < 12 || mod100 > 19)) return("few")
  "other"
}

